const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),crypto=require('node:crypto');
const invoices=require('./invoices'),zip=require('./invoice-bundle-zip'),{crc32}=require('./xlsx-values'),{createServer}=require('./server'),{saveAdmin}=require('./auth');
const actor={id:'reader',username:'Reader',companyId:'default',locationId:'store',locationName:'Café North'},week='2026-10-05';
function input(name='scan.png',suffix='one',extra={}){const pdf=name.endsWith('.pdf'),bytes=Buffer.from(pdf?'%PDF-1.4\nSynthetic invoice '+suffix:Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),Buffer.from('Synthetic invoice '+suffix)]));return{id:crypto.randomUUID(),weekStart:week,supplier:'Test supplier',invoiceNumber:'TEST-'+suffix,invoiceDate:'2026-10-11',notes:'Synthetic invoice',subtotalCents:100,taxCents:0,totalCents:100,source:{name,mime:pdf?'application/pdf':'image/png',data:bytes.toString('base64')},preview:null,ocrText:'Synthetic test invoice '+suffix,pages:1,confidence:100,...extra};}
// Read the central directory independently, including UTF-8 names, stored bytes,
// local offsets, checksums and descriptors. Python zipfile also verifies browser exports.
function unzip(bytes){const end=bytes.length-22;assert.equal(bytes.readUInt32LE(end),0x06054b50);const count=bytes.readUInt16LE(end+10),offset=bytes.readUInt32LE(end+16);assert.equal(bytes.readUInt32LE(end+12),end-offset);let position=offset;const result=[];for(let n=0;n<count;n++){assert.equal(bytes.readUInt32LE(position),0x02014b50);assert.equal(bytes.readUInt16LE(position+8),0x0808);assert.equal(bytes.readUInt16LE(position+10),0);const crc=bytes.readUInt32LE(position+16),size=bytes.readUInt32LE(position+24),nameLength=bytes.readUInt16LE(position+28),name=bytes.subarray(position+46,position+46+nameLength).toString('utf8'),local=bytes.readUInt32LE(position+42);assert.equal(bytes.readUInt32LE(local),0x04034b50);assert.equal(bytes.readUInt16LE(local+6),0x0808);const start=local+30+bytes.readUInt16LE(local+26)+bytes.readUInt16LE(local+28),data=bytes.subarray(start,start+size);assert.equal(bytes.subarray(local+30,start).toString('utf8'),name);assert.equal(crc32(data),crc);assert.equal(bytes.readUInt32LE(start+size),0x08074b50);assert.equal(bytes.readUInt32LE(start+size+4),crc);assert.equal(bytes.readUInt32LE(start+size+8),size);assert.equal(bytes.readUInt32LE(start+size+12),size);result.push({name,data});position+=46+nameLength+bytes.readUInt16LE(position+30)+bytes.readUInt16LE(position+32);}assert.equal(position,end);return result;}
async function bytes(archive){const output=[];try{for await(const chunk of archive.chunks())output.push(chunk);return Buffer.concat(output);}finally{await archive.close();}}
test('weekly ZIPs contain every original image/PDF once, with safe unique UTF-8 names and unchanged bytes',async()=>{
 assert(Buffer.byteLength(zip.label('𠮷'.repeat(100)))<=160);assert(!zip.label('𠮷'.repeat(100)).includes('\ufffd'));const long=zip.plan([{record:{supplier:'𠮷'.repeat(60),source:{name:'scan.png',mime:'image/png'}},size:1}]).entries[0].name;assert(long.length<255);assert(long.toString().endsWith('.png'));assert(!long.toString().includes('\ufffd'));const dir=await fs.mkdtemp('/tmp/invoice-bundle-');try{const originals=[input('Café:scan?.png','one',{supplier:'Café / Supplies:*?'}),input('scan.png','two'),input('scan.png','three',{supplier:''}),input('invoice.pdf','four')];for(const value of originals)await invoices.create(dir,actor,value);await invoices.update(dir,actor,originals[1].id,{...originals[1],revision:1,supplier:'Oroso Poultry'});await invoices.create(dir,actor,input('other.png','other',{weekStart:'2026-10-12'}));await invoices.create(dir,{...actor,locationId:'elsewhere'},input('private.png','private'));const before=await invoices.list(dir,actor),archive=await invoices.bundle(dir,actor,week),output=await bytes(archive),files=unzip(output);assert.equal(output.length,archive.size);assert.equal(archive.count,4);assert.equal(files.length,4);assert.equal(new Set(files.map(f=>f.name.toLowerCase())).size,4);assert(files.some(f=>f.name.includes('Café')));for(const file of files){assert.match(file.name,/^\d{4}-[^/\\:*?"<>|]+\.(?:png|pdf)$/u);const original=originals.find(value=>Buffer.from(value.source.data,'base64').equals(file.data));assert(original);const supplier=original.id===originals[1].id?'Oroso Poultry':original.supplier.trim()||'Unknown supplier';assert(file.name.includes(zip.label(supplier)));}assert.deepEqual(await invoices.list(dir,actor),before);assert.match(archive.name,/^invoices-Café North-2026-10-05\.zip$/);await archive.close();for(const invalid of ['2026-10-06','2026-02-30','../outside',''])await assert.rejects(invoices.bundle(dir,actor,invalid),e=>e.status===400);await assert.rejects(invoices.bundle(dir,actor,'2026-11-02'),e=>e.status===404);}finally{await fs.rm(dir,{recursive:true,force:true});}
});
test('bundle snapshots survive later invoice moves/deletion and close file handles on early cancellation',async t=>{
 const dir=await fs.mkdtemp('/tmp/invoice-bundle-snapshot-');try{const first=input('scan.png','first'),second=input('invoice.pdf','second');await invoices.create(dir,actor,first);await invoices.create(dir,actor,second);const archive=await invoices.bundle(dir,actor,week);await invoices.remove(dir,actor,first.id,1);await invoices.update(dir,actor,second.id,{...second,revision:1,weekStart:'2026-10-12'});assert.equal(unzip(await bytes(archive)).length,2);await assert.rejects(invoices.bundle(dir,actor,week),e=>e.status===404);
  const handles=[],open=fs.open;t.mock.method(fs,'open',async(...args)=>{const handle=await open(...args);handles.push(handle);return handle;});const cancelled=await invoices.bundle(dir,actor,'2026-10-12'),iterator=cancelled.chunks();await iterator.next();await iterator.return();assert(handles.length);assert(handles.every(handle=>handle.fd===-1));await cancelled.close();
 }finally{await fs.rm(dir,{recursive:true,force:true});}
});
test('missing or damaged originals fail the whole bundle rather than silently excluding invoices',async()=>{
 const dir=await fs.mkdtemp('/tmp/invoice-bundle-damaged-');try{const value=input();await invoices.create(dir,actor,value);const target=path.join(dir,'invoices',actor.locationId,value.id,'source.bin');await fs.writeFile(target,Buffer.alloc(Buffer.from(value.source.data,'base64').length,65));const archive=await invoices.bundle(dir,actor,week);await assert.rejects(bytes(archive),/original changed/);await fs.rm(target);await assert.rejects(invoices.bundle(dir,actor,week),e=>e.status===409);assert.equal((await invoices.list(dir,actor)).bundles[0].count,1);assert.throws(()=>zip.plan([{record:{source:{name:'too-big.pdf',mime:'application/pdf'}},size:0xffffffff-50}]),/too large/);}finally{await fs.rm(dir,{recursive:true,force:true});}
});
test('bundle downloads are read-only, invoice-view protected and limited to the requested location and saved bundle week',async()=>{
 const dir=await fs.mkdtemp('/tmp/invoice-bundle-api-');await saveAdmin(dir,'Office','test-office-password');const server=createServer(dir,{fetchImpl:()=>{throw Error('Unexpected provider request');}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port;
 async function request(actor,url,method='GET',body,extra={}){return fetch(base+url,{method,headers:{'Content-Type':'application/json',...actor?.headers,...extra},body:body===undefined?undefined:JSON.stringify(body)});}
 async function api(...args){const response=await request(...args);assert(response.ok,await response.clone().text());return response.json();}
 async function login(username){const response=await request(null,'/api/login','POST',{username,password:'test-office-password'}),cookie=response.headers.get('set-cookie').split(';')[0],session=await api({headers:{Cookie:cookie}},'/api/session');return{session,headers:{Cookie:cookie,'X-CSRF-Token':session.csrf}};}
 try{const office=await login('Office');for(const[name,permissions]of [['Viewer',['home.view','invoices.view']],['No invoices',['home.view']]]){const current=await api(office,'/api/permission-levels'),roles=await api(office,'/api/permission-levels','POST',{revision:current.revision,name,level:10,scope:'company',permissions}),role=roles.levels.find(r=>r.name===name);await api(office,'/api/accounts','POST',{username:name,password:'test-office-password',role:role.id,companyId:office.session.companyId,locationId:office.session.locationId});}const viewer=await login('Viewer'),none=await login('No invoices'),other=await api(office,'/api/locations','POST',{name:'Private store'});await api(office,'/api/invoices','POST',input());await api(office,'/api/invoices','POST',input('next.png','next',{weekStart:'2026-10-12'}));await api(office,'/api/invoices','POST',input('secret.png','secret'),{'X-Location-Id':other.id});const before=await api(office,'/api/invoices'),catalogue=await fs.readFile(path.join(dir,'catalogue.json'),'utf8').catch(e=>{if(e.code!=='ENOENT')throw e;return null;}),route='/api/invoices/bundles/'+week+'/download?location='+viewer.session.locationId;
  assert.equal((await request(null,route)).status,401);assert.equal((await request(none,route)).status,403);assert.equal((await request(viewer,route,'GET',undefined,{'X-Location-Id':other.id})).status,403);assert.equal((await request(viewer,route.replace(viewer.session.locationId,other.id))).status,409);assert.equal((await request(viewer,route.replace(week,'2026-10-06'))).status,400);assert.equal((await request(viewer,route.replace(week,'2026-11-02'))).status,404);
  const result=await request(viewer,route);assert.equal(result.status,200);assert.equal(result.headers.get('content-type'),'application/zip');assert.match(result.headers.get('content-disposition'),/^attachment; filename\*=UTF-8''invoices-/);assert.match(result.headers.get('cache-control'),/no-store/);const downloaded=Buffer.from(await result.arrayBuffer());assert.equal(Number(result.headers.get('content-length')),downloaded.length);assert.equal(unzip(downloaded).length,1);assert.deepEqual(await api(office,'/api/invoices'),before);assert.equal(await fs.readFile(path.join(dir,'catalogue.json'),'utf8').catch(e=>{if(e.code!=='ENOENT')throw e;return null;}),catalogue);assert.equal((await request(viewer,'/api/invoices','POST',input('blocked.png','blocked'))).status,403);
 }finally{await new Promise(r=>server.close(r));await fs.rm(dir,{recursive:true,force:true});}
});
